#!/usr/bin/env python3
"""Generate the final HTML report from computed data and charts."""

import json

with open('/app/report_data.json') as f:
    data = json.load(f)

rd = data['report_data']
charts = data['charts']
yearly_data = data['yearly_data']
author_data = data['author_data']
price_segment_data = data['price_segment_data']
genre_year_data = data['genre_year_data']
rating_range_data = data['rating_range_data']
yoy_price_changes = data['yoy_price_changes']
yoy_rating_changes = data['yoy_rating_changes']
max_price_rise = data['max_price_rise']
max_price_drop = data['max_price_drop']
max_rating_rise = data['max_rating_rise']
max_rating_drop = data['max_rating_drop']

# Find max-price year and min-price year from yearly_data
max_price_year = max(yearly_data, key=lambda x: x['avg_price'])
min_price_year = min(yearly_data, key=lambda x: x['avg_price'])
max_rating_year = max(yearly_data, key=lambda x: x['avg_rating'])
min_rating_year = min(yearly_data, key=lambda x: x['avg_rating'])

# Fiction vs non-fiction yearly extremes
fic_max_price = max((y for y in yearly_data if y['fic_avg_price'] is not None), key=lambda x: x['fic_avg_price'])
fic_min_price = min((y for y in yearly_data if y['fic_avg_price'] is not None), key=lambda x: x['fic_avg_price'])
nonfic_max_price = max((y for y in yearly_data if y['nonfic_avg_price'] is not None), key=lambda x: x['nonfic_avg_price'])
nonfic_min_price = min((y for y in yearly_data if y['nonfic_avg_price'] is not None), key=lambda x: x['nonfic_avg_price'])

def format_num(n):
    if n is None:
        return '—'
    return f'{n:,.0f}'

def format_price(n):
    if n is None:
        return '—'
    return f'${n:,.2f}'

def correlation_label(r, p, significant):
    strength = 'negligible'
    ar = abs(r)
    if ar < 0.1:
        strength = 'negligible'
    elif ar < 0.3:
        strength = 'weak'
    elif ar < 0.5:
        strength = 'moderate'
    elif ar < 0.7:
        strength = 'strong'
    else:
        strength = 'very strong'
    direction = 'negative' if r < 0 else 'positive'
    sig = 'statistically significant' if significant else 'not statistically significant'
    return f'{strength} {direction} ({sig}, p={p:.4f})'

