def format_num(n):
    if n is None:
        return '—'
    return f'{n:,.0f}'

def format_price(n):
    if n is None:
        return '—'
    return f'${n:,.2f}'

def correlation_label(r, p, significant):
    strength = 'negligible'
    ar = abs(r)
    if ar < 0.1:
        strength = 'negligible'
    elif ar < 0.3:
        strength = 'weak'
    elif ar < 0.5:
        strength = 'moderate'
    elif ar < 0.7:
        strength = 'strong'
    else:
        strength = 'very strong'
    direction = 'negative' if r < 0 else 'positive'
    sig = 'statistically significant' if significant else 'not statistically significant'
    return f'{strength} {direction} ({sig}, p={p:.4f})'

